const equal=(a,b)=>assert.equal(canonical(a),canonical(b));
const barrier=()=>{let resolve;const promise=new Promise(done=>{resolve=done;});return {promise,resolve};};
async function scene(extra={}){const f=await currentAllocationFixtureV260(),c=new Client({...f.props,...extra});await c.open();return {...f,c};}
async function quote(s){await s.c.changeForm({model_id:s.model.id,note:'保留原报告目录，只在当前配置整理两条合成要求',reviewed:true});assert.equal(await s.c.prepare(),true,s.c.error);return s.c.preview;}
async function started(s){await quote(s);s.c.acknowledge(true);assert.equal(await s.c.start(),true,s.c.error);return s.c.selected;}
async function answered(s){const row=await started(s);s.complete(s.state.rows.get(row.id));await s.c.refresh();return s.c.selected;}
const posts=(s,suffix)=>s.state.posts.filter(r=>r.path.endsWith(suffix));
async function unknownStart(s){await quote(s);s.c.acknowledge(true);s.state.mode='unknown';assert.equal(await s.c.start(),false);assert.ok(s.c.pendingRecord);return copy(s.c.pendingRecord);}
async function closeReason(s,reason='保留两份原文，不再按此原号启动；实际费用仍未知'){await s.c.editCloseReason(reason);s.state.mode='normal';}

test('V260 M2 native model directory remains genuine V213 while consumer profile is independent',async()=>{const s=await scene();equal(currentAllocationModelsV260([s.model]),[s.model]);assert.equal(s.model.generation_profile,'catalogue-allocation-v213');assert.deepEqual(currentAllocationModelsV260([{...s.model,generation_profile:PROFILE}]),[]);assert.notEqual(s.prefix,'ga-catalogue-allocation-v213:'+ids.workspace+':'+ids.actor+':'+ids.producer+':'+s.workingId);s.c.dispose();});
