test('V260 M2 current context separates source25 and target35 and allows an honest empty blocked business directory',async()=>{const s=await scene(),value=checkedCurrentAllocationContextV260(s.context(),s.scope);assert.equal(value.source_revision,25);assert.equal(value.target_configuration.revision,35);const empty={...copy(value),businesses:[],permissions:{can_request_preview:false},reason:'业务定义尚未就绪',validation:{...copy(value.validation),issues:[{code:'no_businesses',path:'businesses',message:'尚无业务定义',blocks_confirmation:true}],catalogue_blockers:[{code:'no_businesses',path:'businesses',message:'尚无业务定义',blocks_confirmation:true}],catalogue_structurally_ready:false}};checkedCurrentAllocationContextV260(empty,s.scope);for(const mutate of [v=>{v.source_revision=35;},v=>{v.binding_id=id(99);},v=>{v.can_dispatch=true;},v=>{v.native_preparation={};},v=>{v.default_target_positions=[1,0];}]){const bad=copy(value);mutate(bad);assert.throws(()=>checkedCurrentAllocationContextV260(bad,s.scope));}s.c.dispose();});
