test('V260 M2 attempted unknown retains original and cannot be retired from foundfalse or a 409 error',async()=>{const s=await scene();await quote(s);s.c.acknowledge(true);s.state.mode='unknown';assert.equal(await s.c.start(),false);const p=copy(s.c.pendingRecord),writes=posts(s,'/start-allocation').length;assert.equal(s.c.guard(),true);assert.equal(s.c.guard({write:true}),false);assert.equal(await s.c.retireOriginal(),false);assert.equal(s.c.pendingRecord.raw,p.raw);s.c.dispose();const next=new Client(s.props);await next.open();await next.recoverOriginal();assert.equal(posts(s,'/start-allocation').length,writes);assert.equal(next.pendingRecord.raw,p.raw);assert.equal(next.view().canRetirePending,false);s.state.mode='normal';assert.equal(await next.continueOriginal(),true,next.error);assert.equal(posts(s,'/start-allocation').at(-1).raw,p.raw);assert.equal(s.state.commands.size,1);next.dispose();});
