test('V260 M2 cold accepted pending open performs one fresh context and inventory read while retaining exact original and real receipt',async()=>{const s=await scene();await quote(s);s.c.acknowledge(true);s.state.mode='lost';assert.equal(await s.c.start(),false);const p=copy(s.c.pendingRecord),raw=s.f.storage.getItem(s.prefix+'original:'+p.request_id),sent=posts(s,'/start-allocation').length;s.c.dispose();s.state.lookupBlocked=false;const begin=s.state.calls.length,next=new Client(s.props);await next.open();const calls=s.state.calls.slice(begin),contextPath='/setup/report-business-catalogues/v260/current-contexts/bindings/'+s.binding.id+'/allocation-context',listPath=BASE+'?producer_id='+ids.producer;for(const path of [contextPath,listPath]){const matching=calls.map((row,index)=>({row,index})).filter(({row})=>row.method==='GET'&&row.path===path);assert.equal(matching.length,1,'cold accepted open must perform exactly one fresh '+path);const at=matching[0].index;assert.equal(calls[at-1].path,'/me');assert.equal(calls[at+1].path,'/me');}assert.equal(next.pendingRecord,null);assert.equal(next.selected.id,s.state.commands.get(p.request_id).id);assert.equal(next.context.permissions.can_request_preview,true);assert.equal(next.guard({write:true}),false,'a real queued activity still blocks fresh paid work');assert.equal(s.f.storage.getItem(s.prefix+'original:'+p.request_id),raw);equal(JSON.parse(s.f.storage.getItem(s.prefix+'receipt:'+p.request_id)).result,s.state.commands.get(p.request_id));assert.equal(posts(s,'/start-allocation').length,sent);next.dispose();});
test('V260 M2 explicit lookup still refreshes a found receipt once and keeps an unknown original without refresh or POST',async()=>{const s=await scene();await quote(s);s.c.acknowledge(true);s.state.mode='lost';assert.equal(await s.c.start(),false);const p=copy(s.c.pendingRecord),before=s.state.calls.length,sent=posts(s,'/start-allocation').length;s.state.lookupBlocked=false;assert.equal(await s.c.lookup(p),true);const calls=s.state.calls.slice(before),contextPath='/setup/report-business-catalogues/v260/current-contexts/bindings/'+s.binding.id+'/allocation-context';assert.equal(calls.filter(r=>r.method==='GET'&&r.path===contextPath).length,1);assert.equal(calls.filter(r=>r.method==='GET'&&r.path===BASE+'?producer_id='+ids.producer).length,1);assert.equal(s.c.pendingRecord,null);assert.equal(s.c.selected.activity_id,p.request_id);assert.equal(posts(s,'/start-allocation').length,sent);s.c.dispose();const unknown=await scene(),original=await unknownStart(unknown),raw=unknown.f.storage.getItem(unknown.prefix+'original:'+original.request_id),startCount=posts(unknown,'/start-allocation').length,readBegin=unknown.state.calls.length;assert.equal(await unknown.c.lookup(original),false);const reads=unknown.state.calls.slice(readBegin);assert.ok(reads.some(r=>r.method==='GET'&&r.path===BASE+'/requests/'+original.request_id+'?'+new URLSearchParams({expected_sha256:original.sha256})));assert.equal(reads.some(r=>r.path.endsWith('/allocation-context')||r.path===BASE+'?producer_id='+ids.producer),false);assert.equal(unknown.c.pendingRecord.raw,original.raw);assert.equal(unknown.c.pendingRecord.sha256,original.sha256);assert.equal(unknown.f.storage.getItem(unknown.prefix+'original:'+original.request_id),raw);assert.equal(unknown.c.guard(),true);assert.equal(unknown.c.guard({write:true}),false);assert.equal(posts(unknown,'/start-allocation').length,startCount);unknown.c.dispose();});
test('V260 M2 superseded open cannot clear current loading or inject its epoch error while accepted recovery waits for fresh context',async()=>{const s=await scene();await quote(s);s.c.acknowledge(true);s.state.mode='lost';assert.equal(await s.c.start(),false);const p=copy(s.c.pendingRecord),raw=s.f.storage.getItem(s.prefix+'original:'+p.request_id),sent=posts(s,'/start-allocation').length;s.c.dispose();s.state.lookupBlocked=false;const oldStarted=barrier(),oldRelease=barrier(),currentStarted=barrier(),currentRelease=barrier(),contextPath='/setup/report-business-catalogues/v260/current-contexts/bindings/'+s.binding.id+'/allocation-context';let firstIdentity=true,previous,current;const c=new Client({...s.props,api:async(path,options)=>{const old=path==='/me'&&firstIdentity;if(old)firstIdentity=false;const value=await s.api(path,options);if(old){oldStarted.resolve();await oldRelease.promise;}if(path===contextPath){currentStarted.resolve();await currentRelease.promise;}return value;}});try{c.epoch++;previous=c.open();await oldStarted.promise;c.dispose();c.closed=false;c.epoch++;current=c.open();await currentStarted.promise;oldRelease.resolve();await previous;assert.equal(c.loading,true,'the superseded open must not announce completion of the live source check');assert.equal(c.error,'','an old epoch error must not become the current page error');assert.equal(c.activitiesLoaded,false);assert.equal(c.pendingRecord,null);assert.equal(c.selected.activity_id,p.request_id);assert.equal(s.f.storage.getItem(s.prefix+'original:'+p.request_id),raw);currentRelease.resolve();await current;assert.equal(c.loading,false);assert.equal(c.error,'');assert.equal(c.activitiesLoaded,true);assert.equal(c.context.permissions.can_request_preview,true);assert.equal(c.selected.id,s.state.commands.get(p.request_id).id);equal(JSON.parse(s.f.storage.getItem(s.prefix+'receipt:'+p.request_id)).result,s.state.commands.get(p.request_id));assert.equal(posts(s,'/start-allocation').length,sent);}finally{oldRelease.resolve();currentRelease.resolve();await Promise.allSettled([previous,current].filter(Boolean));c.dispose();}});
test('V260 M2 stale refresh rejection preserves the new context and cannot initiate another inventory read',async()=>{const s=await scene(),started=barrier(),release=barrier(),contextPath='/setup/report-business-catalogues/v260/current-contexts/bindings/'+s.binding.id+'/allocation-context';let firstContext=true,previous;s.c.api=async(path,options)=>{const old=path===contextPath&&firstContext;if(old)firstContext=false;const value=await s.api(path,options);if(old){started.resolve();await release.promise;}return value;};try{previous=s.c.refresh().then(()=>null,error=>error);await started.promise;s.c.dispose();s.c.closed=false;s.c.epoch++;await s.c.refresh();const context=copy(s.c.context),items=copy(s.c.items),before=s.state.calls.length;release.resolve();const error=await previous;assert.match(error?.message||'',/账号、目录或页面已变化/);equal(s.c.context,context);equal(s.c.items,items);assert.equal(s.c.activitiesLoaded,true);assert.equal(s.c.inventoryFresh,true);assert.equal(s.state.calls.slice(before).some(row=>row.path===BASE+'?producer_id='+ids.producer),false,'a stale context failure must not start a fresh-generation inventory read');assert.equal(s.state.posts.length,0);}finally{release.resolve();if(previous)await previous;s.c.dispose();}});
