test('V260 M2 actual StrictMode keeps the live loading state and disabled controls when the previous identity response arrives late',()=>harness(async h=>{const oldStarted=barrier(),oldRelease=barrier(),oldReturned=barrier(),currentStarted=barrier(),currentRelease=barrier(),contextPath='/setup/report-business-catalogues/v260/current-contexts/bindings/'+h.binding.id+'/allocation-context';let firstIdentity=true;const api=async(path,options)=>{const old=path==='/me'&&firstIdentity;if(old)firstIdentity=false;const value=await h.api(path,options);if(old){oldStarted.resolve();await oldRelease.promise;oldReturned.resolve();}if(path===contextPath){currentStarted.resolve();await currentRelease.promise;}return value;};try{await h.mount({api});await oldStarted.promise;await currentStarted.promise;await act(async()=>{oldRelease.resolve();await oldReturned.promise;});assert.match(h.text(),/正在读取已保存目录、原申请和真实归类进度/);assert.equal(h.container.querySelector('[role="alert"]'),null);assert.equal(h.field('补充说明（可选）').matches(':disabled'),true);assert.equal(h.button('刷新归类活动与目录').matches(':disabled'),true);assert.equal(h.guard()(),false);await act(async()=>currentRelease.resolve());await h.until(()=>!h.text().includes('正在读取已保存目录、原申请和真实归类进度')&&h.field('本次使用的模型')&&!h.field('本次使用的模型').matches(':disabled'));assert.equal(h.container.querySelector('[role="alert"]'),null);assert.match(h.text(),/当前目录还没有这类归类活动/);assert.equal(h.state.posts.length,0);}finally{oldRelease.resolve();currentRelease.resolve();}}));
test('V260 M2 actual React unknown full unmount keeps original note and pending then readonly restores with no new POST',()=>harness(async h=>{await h.mount();await h.fill();await h.click('核对本批资料与真实报价');await h.check('我已核对本批发送资料和费用');h.state.mode='unknown';await h.click('确认费用并开始本批整理');const ready=()=>h.container.querySelector('[aria-label="本批原申请恢复"]')&&posts(h,'/start-allocation').length===1&&h.f.storage.getItem(h.prefix+'pending')!==null&&h.button('核对原申请结果')&&!h.button('核对原申请结果').matches(':disabled');await h.until(ready);const pointer=JSON.parse(h.f.storage.getItem(h.prefix+'pending')),original=JSON.parse(h.f.storage.getItem(h.prefix+'original:'+pointer.request_id));await checkedCurrentAllocationOriginalV260(original,h.scope);const raw=original.raw;assert.equal(posts(h,'/start-allocation')[0].raw,raw);assert.equal(h.guard()(),true);await h.unmount();await h.mount();await h.until(ready);assert.equal(h.field('补充说明（可选）').value,'当前配置专属的本机补充说明');assert.equal(h.f.storage.getItem(h.prefix+'original:'+pointer.request_id),JSON.stringify(original));assert.equal(JSON.parse(h.f.storage.getItem(h.prefix+'pending')).request_id,pointer.request_id);await h.click('核对原申请结果');await h.until(()=>h.button('核对原申请结果')&&!h.button('核对原申请结果').matches(':disabled'));assert.equal(posts(h,'/start-allocation').length,1);assert.equal(h.button('核对并归档尚未尝试提交的申请'),undefined);assert.match(h.text(),/结果仍未知/);}));
test('V260 M2 actual managed editor invokes new family through parent adapter and leaves source directory and legacy confirmation untouched',()=>harness(async h=>{await h.mount({mode:'editor'});await h.until(()=>h.container.querySelector('[aria-label="当前配置独立工作副本"]'));await h.click('在当前配置自动整理未归类要求');await h.fill();await h.click('核对本批资料与真实报价');await h.check('我已核对本批发送资料和费用');await h.click('确认费用并开始本批整理');await h.until(()=>h.state.rows.size===1&&h.text().includes('已保存，等待整理'));assert.equal(posts(h,'/start-allocation')[0].body.generation_profile,PROFILE);assert.equal(h.f.state.rows.get(ids.draft).version,5);assert.equal(h.button('确认业务目录并生成范围计划'),undefined);assert.match(h.text(),/目标为第35版配置/);assert.match(h.text(),/报告原来源仍为第25版/);}));
test('V260 M2 actual managed renderer accepts the real semantic version model directory without starting a call',()=>harness(async h=>{h.model.version='1.0.0';const source=copy(h.f.state.rows.get(ids.draft));await h.mount({mode:'editor'});await h.until(()=>h.container.querySelector('[aria-label="当前配置独立工作副本"]'));await h.click('在当前配置自动整理未归类要求');await h.until(()=>h.field('本次使用的模型')&&!h.field('本次使用的模型').matches(':disabled'));const select=h.field('本次使用的模型'),option=[...select.options].find(row=>row.value===h.model.id);assert.ok(option,'the genuine V213 semantic-version model must remain selectable in the Current renderer');assert.equal(option.textContent,h.model.name);await h.change(select,h.model.id);await h.until(()=>h.field('本次使用的模型').value===h.model.id&&h.guard()&&h.guard()());assert.equal(h.model.version,'1.0.0');assert.equal(h.state.posts.length,0);equal(h.f.state.rows.get(ids.draft),source);assert.equal(h.button('确认业务目录并生成范围计划'),undefined);}));
test('V260 M2 actual full Workspace rediscovers managed journal after remount and new inventory stays separate from catalogue sources',()=>harness(async h=>{await h.mount({mode:'parent'});await h.click('查看这次活动');await h.click('核对并编辑这份业务目录');await h.click('打开第2份目录');await h.until(()=>h.container.querySelector('[aria-label="当前配置独立工作副本"]'));await h.click('在当前配置自动整理未归类要求');await h.until(()=>h.field('补充说明（可选）'));await h.change(h.field('补充说明（可选）'),'完整父页面重挂仍保留的当前配置说明');await h.unmount();await h.mount({mode:'parent'});await h.click('查看这次活动');await h.click('核对并编辑这份业务目录');await h.click('打开第2份目录');await h.until(()=>h.field('补充说明（可选）')?.value==='完整父页面重挂仍保留的当前配置说明');assert.equal(h.state.posts.length,0);assert.equal(h.guard()(),true);}));
test('V260 M2 actual React quota leaves explanation editable and parent leave blocked until reliable repair',()=>harness(async h=>{await h.mount({mode:'editor'});await h.click('在当前配置自动整理未归类要求');await h.until(()=>h.field('补充说明（可选）'));h.f.storage.failSet=k=>k.startsWith(h.prefix+'human:');await h.change(h.field('补充说明（可选）'),'尚未写入本机的当前归类要求');await h.until(()=>h.text().includes('本机要求或原申请尚未可靠保存'));assert.equal(h.guard()(),false);assert.equal(h.field('补充说明（可选）').matches(':disabled'),false);h.f.storage.failSet=null;await h.change(h.field('补充说明（可选）'),'修复后可靠保存的归类要求');await h.until(()=>h.guard()()===true);assert.equal(h.state.posts.length,0);}));
test('V260 M2 actual React shows per-decision adoption and real saved child while leaving unselected original requirements',()=>harness(async h=>{await h.mount({mode:'editor'});await h.click('在当前配置自动整理未归类要求');await h.fill();await h.click('核对本批资料与真实报价');await h.check('我已核对本批发送资料和费用');await h.click('确认费用并开始本批整理');await h.until(()=>h.state.rows.size===1&&h.button('刷新归类活动与目录')&&!h.button('刷新归类活动与目录').matches(':disabled'));h.complete([...h.state.rows.values()][0]);await h.click('刷新归类活动与目录');await h.until(()=>h.container.querySelectorAll('.allocation-decision').length===2&&h.container.querySelector('.allocation-decision input[type="checkbox"]')&&!h.container.querySelector('.allocation-decision input[type="checkbox"]').matches(':disabled'));const choices=[...h.container.querySelectorAll('.allocation-decision input[type="checkbox"]')];assert.equal(choices[0].matches(':disabled'),false);await act(async()=>choices[0].click());await h.click('核对所选建议的保存变化');assert.equal(posts(h,'/apply-current-allocation').length,0);await h.click('采纳并保存所选建议');await h.until(()=>posts(h,'/apply-current-allocation').length===1&&h.text().includes('所选建议已真实保存'));assert.equal(h.f.state.rows.get(h.workingId).version,3);assert.equal(h.f.state.rows.get(ids.draft).version,5);assert.ok(h.f.state.rows.get(h.workingId).document.questions.length);assert.equal(h.button('确认业务目录并生成范围计划'),undefined);}));
async function unknownDOM(h){await h.fill();await h.click('核对本批资料与真实报价');await h.check('我已核对本批发送资料和费用');h.state.mode='unknown';await h.click('确认费用并开始本批整理');await h.until(()=>h.field('关闭原申请的说明')&&!h.field('关闭原申请的说明').matches(':disabled')&&posts(h,'/start-allocation').length===1);const pointer=JSON.parse(h.f.storage.getItem(h.prefix+'pending'));return JSON.parse(h.f.storage.getItem(h.prefix+'original:'+pointer.request_id));}
test('V260 M2 actual React close response loss remount restores both raws readonly and requires explicit new conditions',()=>harness(async h=>{await h.mount();const original=await unknownDOM(h);await h.change(h.field('关闭原申请的说明'),'两份原文继续保留，不再按原号启动；不认定未收费');await h.until(()=>h.button('关闭原申请，保留记录')&&!h.button('关闭原申请，保留记录').matches(':disabled'));h.state.mode='close_lost';await h.click('关闭原申请，保留记录');await h.until(()=>h.container.querySelector('[aria-label="原关闭申请恢复"]')&&h.button('核对原申请结果')&&!h.button('核对原申请结果').matches(':disabled'));const closing=JSON.parse(h.f.storage.getItem(h.prefix+'closure-original:'+original.request_id));assert.equal(h.f.storage.getItem(h.prefix+'pending')!==null,true);assert.equal(h.guard()(),true);await h.unmount();h.state.lookupBlocked=false;await h.mount();await h.until(()=>h.container.querySelector('[aria-label="已保留原申请关闭记录"]')&&h.button('保留要求，核对新的整理条件')&&!h.button('保留要求，核对新的整理条件').matches(':disabled'));const archive=JSON.parse(h.f.storage.getItem(h.prefix+'closure-archive:'+original.request_id));assert.equal(archive.original.raw,original.raw);assert.equal(archive.closing.raw,closing.raw);assert.equal(posts(h,'/close').length,1);assert.equal(posts(h,'/start-allocation').length,1);assert.match(h.text(),/过去是否发送及费用不作断言/);assert.equal(h.button('核对本批资料与真实报价').matches(':disabled'),true);const count=h.state.posts.length;await h.click('保留要求，核对新的整理条件');await h.until(()=>h.button('保留要求，核对新的整理条件')===undefined);assert.equal(h.state.posts.length,count);assert.equal(h.field('补充说明（可选）').value,'当前配置专属的本机补充说明');}));
test('V260 M2 actual React start wins close race and shows the actual task instead of a false closed result',()=>harness(async h=>{await h.mount();const original=await unknownDOM(h);await h.change(h.field('关闭原申请的说明'),'若原启动已经保存，返回原活动而不是虚报关闭');await h.until(()=>h.button('关闭原申请，保留记录')&&!h.button('关闭原申请，保留记录').matches(':disabled'));h.state.mode='close_start_wins';await h.click('关闭原申请，保留记录');await h.until(()=>h.container.querySelector('[aria-label="本批原申请恢复"]')===null&&h.text().includes('已保存，等待整理'));assert.equal([...h.state.rows.values()][0].activity_id,original.request_id);assert.equal(h.container.querySelector('[aria-label="已保留原申请关闭记录"]'),null);assert.equal(h.closures.size,0);assert.equal(posts(h,'/start-allocation').length,1);assert.equal(posts(h,'/close').length,1);}));
test('V260 M2 actual React closing quota preserves editable explanation and original pending until GET archives the saved receipt',()=>harness(async h=>{await h.mount({mode:'editor'});await h.click('在当前配置自动整理未归类要求');const original=await unknownDOM(h);h.f.storage.failSet=k=>k.startsWith(h.prefix+'closing-human:');await h.change(h.field('关闭原申请的说明'),'保存失败的关闭说明仍在本页');await h.until(()=>h.text().includes('关闭说明尚未可靠保留'));assert.equal(h.guard()(),false);assert.equal(h.field('关闭原申请的说明').matches(':disabled'),false);h.f.storage.failSet=null;await h.change(h.field('关闭原申请的说明'),'修正后可靠保存，继续保留原启动和关闭正文');await h.until(()=>h.button('关闭原申请，保留记录')&&!h.button('关闭原申请，保留记录').matches(':disabled'));h.f.storage.failSet=k=>k===h.prefix+'closure-archive:'+original.request_id;h.state.mode='normal';await h.click('关闭原申请，保留记录');await h.until(()=>h.closures.size===1&&h.container.querySelector('[aria-label="原关闭申请恢复"]')&&h.button('核对原申请结果')&&!h.button('核对原申请结果').matches(':disabled'));assert.ok(h.f.storage.getItem(h.prefix+'pending'));assert.equal(h.container.querySelector('[aria-label="已保留原申请关闭记录"]'),null);h.f.storage.failSet=null;await h.click('核对原申请结果');await h.until(()=>h.container.querySelector('[aria-label="已保留原申请关闭记录"]')&&h.f.storage.getItem(h.prefix+'pending')===null);assert.equal(posts(h,'/close').length,1);assert.equal(posts(h,'/start-allocation').length,1);assert.equal(h.f.state.rows.get(ids.draft).version,5);}));
